/**
 * A key number with its label and direction of change (`design/components/stat.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stat.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import {
  Icon,
  claimSlot,
  createDerived,
  scope,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/stat.module.css'
import Badge from './Badge'
import Sparkline from '../charts/Sparkline'

export type DeltaDirection = 'up' | 'down'

export interface StatDelta {
  value: string
  direction: DeltaDirection
  positive?: boolean
}

export interface StatTrend {
  direction: DeltaDirection
  label: string
}

export interface StatFooter {
  primary: string
  secondary: string
}

export interface StatProps {
  delta?: StatDelta
  /**
   * Shown when there is no delta, such as "vs last week".
   */
  description?: string
  /**
   * The two-line footer: the interpretation, then the period it covers.
   */
  footer?: StatFooter
  icon?: IconRole
  label: string
  /**
   * Tabular figures, so a column of these lines up.
   */
  numeric?: boolean
  /**
   * The trend as a shape: a `Sparkline` at the value row's inline end. It can sit beside `trend`
   * (words for the direction, a shape for the path) and replaces neither `delta` nor `footer`.
   * `Sparkline` draws it, and renders nothing for fewer than two points.
   */
  spark?: readonly number[]
  /**
   * The sparkline's accessible name, as a function of the stat's label because the wording
   * belongs to the catalog; the default is `{label}, recent trend`.
   */
  sparkLabel?: (label: string) => string
  /**
   * The neutral movement chip, top-right. See `StatTrend` for why it is not `delta`.
   */
  trend?: StatTrend
  /**
   * Already formatted by the app.
   */
  value: string
}

/** A key number with its label and direction of change. */
export default function Stat(given: StatProps): JSX.Element {
  const props = mergeProps(
    { numeric: true, sparkLabel: (label: string) => `${label}, recent trend` } as Defaults<
      StatProps,
      'numeric' | 'sparkLabel'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const positive = createDerived(() =>
      props.delta === undefined
        ? undefined
        : (props.delta.positive ?? props.delta.direction === 'up'),
    )
    return (
      <div class={styles.stat} data-member="stat">
        {/* labelRow */}
        <div class={styles.labelRow}>
          {/* label */}
          <span class={styles.label}>{props.label}</span>
          {props.icon !== undefined || props.trend !== undefined ? (
            <span class={styles.labelEnd}>
              {props.icon !== undefined ? (
                <span class={styles.glyph}>
                  <Icon name={props.icon} />
                </span>
              ) : null}
              {props.trend !== undefined ? (
                <Badge variant="outline" icon={props.trend.direction}>
                  {props.trend.label}
                </Badge>
              ) : null}
            </span>
          ) : null}
        </div>
        {/* valueRow */}
        <div class={styles.valueRow}>
          {/* value */}
          <span class={styles.value} data-numeric={props.numeric ? '' : undefined}>
            {props.value}
          </span>
          {props.spark !== undefined ? (
            <span class={styles.spark}>
              <Sparkline data={props.spark} label={props.sparkLabel(props.label)} />
            </span>
          ) : null}
        </div>
        {props.delta !== undefined ? (
          <span
            class={styles.delta}
            data-direction={props.delta.direction}
            data-positive={positive.value ? '' : undefined}
          >
            <Icon name={props.delta.direction} size="sm" />
            <span aria-hidden="true">{props.delta.value}</span>
            {/* spoken */}
            <span class={styles.spoken}>
              {`${props.delta.direction} ${props.delta.value} — ${positive.value ? 'positive' : 'negative'}`}
            </span>
          </span>
        ) : props.description !== undefined ? (
          <span class={styles.description}>{props.description}</span>
        ) : null}
        {props.footer !== undefined ? (
          <div class={styles.footer}>
            {/* footerPrimary */}
            <span class={styles.footerPrimary}>
              {props.footer.primary}
              {props.trend !== undefined ? (
                <span class={styles.footerGlyph}>
                  <Icon name={props.trend.direction} size="sm" />
                </span>
              ) : null}
            </span>
            {/* footerSecondary */}
            <span class={styles.footerSecondary}>{props.footer.secondary}</span>
          </div>
        ) : null}
      </div>
    )
  })
}
